effect.shader:
// globais do Node ligados ao motor (tools/nodevideo/ligar_globais.py)
#define _viewport_ratio acProporcaoDoNode
vec4 u_xlat0;
vec4 u_xlat1;
bvec4 u_xlatb1;
vec4 u_xlat2;
bvec2 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
vec2 u_xlat6;
bool u_xlatb6;
vec2 u_xlat12;
bool u_xlatb12;
vec2 u_xlat13;
ivec2 u_xlati13;
bvec2 u_xlatb13;
vec2 u_xlat14;
bvec2 u_xlatb14;
float u_xlat18;
bool u_xlatb18;
void main()
{
    u_xlat0.xy = acScreenNorm.xy + vec2(-0.5, -0.5);
    u_xlat12.xy = vec2(1.0, 1.0) / vec2(_trans_scale.x, _trans_scale.y);
    u_xlat0.xy = u_xlat12.xy * u_xlat0.xy;
    u_xlat12.x = _trans_rotation * 0.0174532942;
    u_xlat1.x = sin(u_xlat12.x);
    u_xlat2.x = cos(u_xlat12.x);
    u_xlat3.x = sin((-u_xlat12.x));
    u_xlat3.y = u_xlat2.x;
    u_xlat3.z = u_xlat1.x;
    u_xlat1.x = dot(u_xlat0.xy, u_xlat3.yz);
    u_xlat1.y = dot(u_xlat0.xy, u_xlat3.xy);
    u_xlat0.xy = u_xlat1.xy + _trans_center.xy;
    if(int(_edge_behaviour) != 0) {
        u_xlatb12 = int(_edge_behaviour)==1;
        u_xlatb1.xy = greaterThanEqual(u_xlat0.xyxx, (-u_xlat0.xyxx)).xy;
        u_xlat13.xy = fract(abs(u_xlat0.xy));
        u_xlat1.x = (u_xlatb1.x) ? u_xlat13.x : (-u_xlat13.x);
        u_xlat1.y = (u_xlatb1.y) ? u_xlat13.y : (-u_xlat13.y);
        u_xlatb13.xy = lessThan(u_xlat0.xyxy, vec4(0.0, 0.0, 0.0, 0.0)).xy;
        u_xlat2.xy = fract(u_xlat0.xy);
        u_xlat2.xy = (-u_xlat2.xy) + vec2(1.0, 1.0);
        u_xlatb14.xy = lessThan(vec4(1.0, 1.0, 1.0, 1.0), u_xlat0.xyxy).xy;
        u_xlati13.xy = ivec2(uvec2((uint(u_xlatb13.x) * 0xffffffffu) | (uint(u_xlatb14.x) * 0xffffffffu), (uint(u_xlatb13.y) * 0xffffffffu) | (uint(u_xlatb14.y) * 0xffffffffu)));
        u_xlat13.x = (u_xlati13.x != 0) ? u_xlat2.x : u_xlat0.x;
        u_xlat13.y = (u_xlati13.y != 0) ? u_xlat2.y : u_xlat0.y;
        u_xlat0.xy = (bool(u_xlatb12)) ? abs(u_xlat1.xy) : u_xlat13.xy;
    }
    u_xlat0.x = texture(pattern_tex, u_xlat0.xy).x;
    u_xlat6.xy = acScreenNorm.xy + (-_trans_center.xy);
    u_xlatb1 = equal(ivec4(int(_direction)), ivec4(1, 2, 3, 4));
    u_xlat6.xy = abs(u_xlat6.xy) + abs(u_xlat6.xy);
    u_xlatb2.xy = equal(ivec4(int(_direction), int(_inverse), int(_direction), int(_direction)), ivec4(5, 1, 0, 0)).xy;
    u_xlat14.xy = vec2(_viewport_ratio.x, _viewport_ratio.y) * _trans_center.xy;
    u_xlat14.xy = acScreenNorm.xy * vec2(_viewport_ratio.x, _viewport_ratio.y) + (-u_xlat14.xy);
    u_xlat18 = dot(u_xlat14.xy, u_xlat14.xy);
    u_xlat18 = sqrt(u_xlat18);
    u_xlat18 = u_xlat18 + u_xlat18;
    u_xlat12.x = (u_xlatb1.w) ? u_xlat6.y : u_xlat18;
    u_xlatb18 = u_xlatb1.w || u_xlatb2.x;
    u_xlat6.x = (u_xlatb1.z) ? u_xlat6.x : u_xlat12.x;
    u_xlatb12 = u_xlatb18 || u_xlatb1.z;
    u_xlat6.x = (u_xlatb1.y) ? acScreenNorm.y : u_xlat6.x;
    u_xlatb12 = u_xlatb12 || u_xlatb1.y;
    u_xlat6.x = (u_xlatb1.x) ? acScreenNorm.x : u_xlat6.x;
    u_xlatb12 = u_xlatb12 || u_xlatb1.x;
    u_xlat6.x = u_xlatb12 ? u_xlat6.x : float(0.0);
    u_xlat12.x = (-u_xlat6.x) + 1.0;
    u_xlat6.x = (u_xlatb2.y) ? u_xlat12.x : u_xlat6.x;
    u_xlat6.x = u_xlat6.x + u_xlat0.x;
    u_xlat6.x = u_xlat6.x * 0.5;
    u_xlat0.x = (int(_direction) != 0) ? u_xlat6.x : u_xlat0.x;
    u_xlat1 = texture(inputImg, acScreenNorm.xy);
    u_xlatb6 = u_xlat0.x<_interpolation;
    u_xlat12.x = _edge_width + _interpolation;
    u_xlat12.x = u_xlat12.x + -0.00999999978;
    u_xlatb12 = u_xlat0.x<u_xlat12.x;
    u_xlat0.x = u_xlat0.x + (-_interpolation);
    u_xlat18 = _edge_width + -0.00999999978;
    u_xlat0.x = u_xlat0.x / u_xlat18;
    u_xlat18 = (-_edge_intensity) + 1.0;
    u_xlat0.x = u_xlat18 + u_xlat0.x;
    u_xlat0.x = u_xlat18 / u_xlat0.x;
    u_xlat0.x = (-u_xlat0.x) + 1.0;
    u_xlat18 = u_xlat1.w * _edge_color.w;
    u_xlat2.w = u_xlat0.x * u_xlat18;
    u_xlat3.xyz = _edge_color.xyz * vec3(0.305306017, 0.305306017, 0.305306017) + vec3(0.682171106, 0.682171106, 0.682171106);
    u_xlat3.xyz = _edge_color.xyz * u_xlat3.xyz + vec3(0.0125228781, 0.0125228781, 0.0125228781);
    u_xlat2.xyz = u_xlat3.xyz * _edge_color.xyz;
    u_xlat2 = u_xlat2.wwww * u_xlat2;
    u_xlat2 = (bool(u_xlatb12)) ? u_xlat2 : u_xlat1;
    u_xlat0 = (bool(u_xlatb6)) ? vec4(0.0, 0.0, 0.0, 0.0) : u_xlat2;
    if(int(_use_inner_mask) != 0) {
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat0;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat1 = u_xlat1 * u_xlat5;
        u_xlat1 = u_xlat3 * u_xlat4 + u_xlat1;
        u_xlat2.x = u_xlat4.x * u_xlat1.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat2.x : u_xlat1.w;
        fragColor.xyz = u_xlat1.xyz;
    } else {
        fragColor = u_xlat0;
    }
    return;
}
